def apply(path: Path):
    text = path.read_text(encoding='utf-8')
    if MARKER_START in text:
        start = text.index(MARKER_START)
        end = text.index(MARKER_END, start) + len(MARKER_END)
        text = text[:start] + text[end:]
    anchor = '\n`;\n\nfunction patchGame(){'
    if anchor not in text:
        raise SystemExit(f'Could not find addon closing marker in {path}')
    text = text.replace(anchor, '\n' + LEGAL_JS.strip() + anchor, 1)
    path.write_text(text, encoding='utf-8')
    print(f'Added legal documentation UI to {path}')


if __name__ == '__main__':
    if len(sys.argv) != 2:
        raise SystemExit('Usage: add_legal_docs.py <html-file>')
    apply(Path(sys.argv[1]))
